/// Member accounts with email/password credentials for authentication. This
/// table serves as the primary identity record for regular members who can
/// create articles, write comments, and participate in discussions. Members
/// have standard permissions for content creation and interaction.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_members {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Unique email address for login and communication.
  email String

  /// Hashed password for authentication using industry-standard cryptographic
  /// hashing.
  password_hash String

  /// Display name shown to other users in the discussion board.
  display_name String

  /// User's biography or profile description text.
  bio String?

  /// Timestamp when the member account was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the member account was last updated.
  updated_at DateTime @db.Timestamptz

  /// Timestamp when the member account was deleted (soft delete). Null if
  /// active.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  sessions discussion_board_member_sessions[]
  memberPasswordResets discussion_board_member_password_resets[]
  memberEmailVerifications discussion_board_member_email_verifications[]
  adminRequest discussion_board_admins?
  actorSystemLogs discussion_board_system_logs[]
  articles discussion_board_articles[]
  comments discussion_board_comments[]
  discussionBoardSearchClicks discussion_board_search_clicks[]
  discussionBoardSearchResults discussion_board_search_results[]
  userBans discussion_board_bans_ban_records[]
  appeals discussion_board_bans_appeals[]
  banLogs discussion_board_bans_admin_logs[]
  adminRequests discussion_board_admins_requests[]
  adminRoles discussion_board_admins_roles[]

  @@unique([email])
  @@index([deleted_at])
}

