import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { DeepPartial } from "@ORGANIZATION/PROJECT-api/lib/typings/DeepPartial";
import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import { randint } from "tstl";
import typia, { tags } from "typia";

import { authorize_member_join } from "../../../authorize/authorize_member_join";
import { authorize_member_login } from "../../../authorize/authorize_member_login";
import { authorize_member_refresh } from "../../../authorize/authorize_member_refresh";

export async function test_api_member_registration_success(
  connection: api.IConnection,
): Promise<void> {
  // Create new connection for registration
  const registerConnection: api.IConnection = { host: connection.host };
  // Generate random member credentials
  const body = {
    // IDiscussionBoardMember.IJoin has no required fields currently
  } satisfies IDiscussionBoardMember.IJoin;
  // Register new member
  const output: IDiscussionBoardMember.IAuthorized =
    await authorize_member_join(registerConnection, {
      body,
    });
  typia.assert(output);
  // Validate response structure
  typia.assert<IAuthorizationToken>(output.token);
  // Verify access token exists and is non-empty
  TestValidator.predicate(
    "access token exists",
    output.token.access.length > 0,
  );
  // Verify refresh token exists and is non-empty
  TestValidator.predicate(
    "refresh token exists",
    output.token.refresh.length > 0,
  );
  // Verify expiration timestamps are valid ISO 8601 format
  TestValidator.predicate(
    "expired_at is valid datetime",
    output.token.expired_at.length > 0,
  );
  TestValidator.predicate(
    "refreshable_until is valid datetime",
    output.token.refreshable_until.length > 0,
  );
  // Verify access token expires after current time
  const now = new Date();
  const expiredAt = new Date(output.token.expired_at);
  TestValidator.predicate("access token not expired", expiredAt > now);
  // Verify refresh token is valid for at least 24 hours
  const refreshableUntil = new Date(output.token.refreshable_until);
  const oneDayFromNow = new Date(now.getTime() + 24 * 60 * 60 * 1000);
  TestValidator.predicate(
    "refresh token valid for at least 24 hours",
    refreshableUntil > oneDayFromNow,
  );
}

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { DeepPartial } from "@ORGANIZATION/PROJECT-api/lib/typings/DeepPartial";
import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import { randint } from "tstl";
import typia, { tags } from "typia";

import { authorize_member_join } from "../../../authorize/authorize_member_join";
import { authorize_member_login } from "../../../authorize/authorize_member_login";
import { authorize_member_refresh } from "../../../authorize/authorize_member_refresh";

export async function test_api_member_login_success(
  connection: api.IConnection,
): Promise<void> {
  // Step 1: Create a member account through join
  const joinConnection: api.IConnection = { host: connection.host };
  const joinOutput = await authorize_member_join(joinConnection, {
    body: typia.random<IDiscussionBoardMember.IJoin>(),
  });
  typia.assert(joinOutput);
  // Step 2: Use the created member's credentials to login
  const loginConnection: api.IConnection = { host: connection.host };
  const loginBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "1234",
  } satisfies IDiscussionBoardMember.ILogin;
  const loginOutput = await authorize_member_login(loginConnection, {
    body: loginBody,
  });
  typia.assert(loginOutput);
  // Step 3: Validate the login response structure
  TestValidator.predicate(
    "has access token",
    () =>
      typeof loginOutput.token.access === "string" &&
      loginOutput.token.access.length > 0,
  );
  TestValidator.predicate(
    "has refresh token",
    () =>
      typeof loginOutput.token.refresh === "string" &&
      loginOutput.token.refresh.length > 0,
  );
  TestValidator.predicate(
    "has valid access token format",
    () => loginOutput.token.access.split(".").length === 3,
  );
  TestValidator.predicate(
    "has valid refresh token format",
    () => loginOutput.token.refresh.split(".").length === 3,
  );
  // Validate expiration timestamps are proper ISO 8601 date-time format
  TestValidator.predicate("has valid expired_at format", () => {
    try {
      new Date(loginOutput.token.expired_at);
      return true;
    } catch {
      return false;
    }
  });
  TestValidator.predicate("has valid refreshable_until format", () => {
    try {
      new Date(loginOutput.token.refreshable_until);
      return true;
    } catch {
      return false;
    }
  });
  // Verify tokens are not empty and different
  TestValidator.notEquals(
    "access and refresh tokens are different",
    loginOutput.token.access,
    loginOutput.token.refresh,
  );
}

