    articleId: string,
    @TypedParam("tagId")
    tagId: string,
  ): Promise<void> {
    try {
      return await deleteDiscussionBoardMemberArticlesArticleIdTagsTagId({
        member,
        articleId,
        tagId,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }
}

